import { FooterNewsletter } from "@/components/design-for-ai/footer-newsletter";

export default function SiteFooter() {
  return (
    <FooterNewsletter
      title="One good email, every Thursday."
      onSubscribe={async (email) => {
        const res = await fetch("/api/subscribe", { method: "POST", body: JSON.stringify({ email }) });
        if (res.status === 409) return "already-subscribed";
        if (!res.ok) throw new Error(String(res.status));
        return "subscribed";
      }}
    />
  );
}
